<?php
namespace App\Http\Controllers\Api\V1;use App\Http\Controllers\Controller;use App\Models\Job;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class PredictiveAnalyticsController extends Controller{public function company(Request $request):JsonResponse{abort_unless($request->user()->account_type==='company',403);$company=$request->user()->companies()->wherePivot('status','active')->firstOrFail();$history=Job::where('company_id',$company->id)->withCount('applications')->whereNotNull('published_at')->get();$average=round((float)$history->avg('applications_count'),1);$conversion=$history->sum('applications_count')?round(DB::table('job_applications')->whereIn('job_id',$history->pluck('id'))->where('status','hired')->count()/$history->sum('applications_count')*100,1):0;return response()->json(['data'=>['expected_applications_next_job'=>$average,'historical_hiring_conversion'=>$conversion,'sample_size'=>$history->count(),'confidence'=>$history->count()>=10?'alta':($history->count()>=3?'media':'baja'),'explanation'=>'Proyección descriptiva basada en vacantes históricas de esta empresa; no utiliza atributos sensibles.']]);}}
